{
  "title": "Discussion on tax calculator app, domain purchase, and product viability",
  "topics": [
    {
      "id": "domain-purchase",
      "title": "Domain purchase consideration",
      "claims": [
        {
          "text": "P4 believes buying a domain is not worthwhile.",
          "evidence": [9]
        },
        {
          "text": "P2 has not bought a domain yet.",
          "evidence": [2]
        },
        {
          "text": "P1 suggests that purchasing the calculator could provide funds for a domain.",
          "evidence": [4]
        }
      ]
    },
    {
      "id": "app-profitability",
      "title": "Profitability of web vs mobile app",
      "claims": [
        {
          "text": "Web platform is less profitable than Android/iOS.",
          "evidence": [11]
        },
        {
          "text": "SEO for a web site is poor; the site does not appear even on the 10th Google results page.",
          "evidence": [11]
        },
        {
          "text": "There is no external traffic from Instagram, X, Threads, or contextual ads.",
          "evidence": [11]
        },
        {
          "text": "A paywall shown within the first 10 seconds leads to almost zero user retention.",
          "evidence": [11]
        }
      ]
    },
    {
      "id": "tech-stack",
      "title": "Technology stack and delivery speed",
      "claims": [
        {
          "text": "Fast delivery (from zero to release in less than a week) is desirable.",
          "evidence": [12]
        },
        {
          "text": "Flutter is recommended as a quick cross‑platform stack.",
          "evidence": [12]
        }
      ]
    },
    {
      "id": "calculator-constraints",
      "title": "Calculator currency handling constraints",
      "claims": [
        {
          "text": "The calculator works only with a Ukrainian‑hryvnia (UAH) FOP and requires conversion using the daily exchange rate.",
          "evidence": [19]
        }
      ]
    },
    {
      "id": "pricing-and-market",
      "title": "Pricing strategy and market interest",
      "claims": [
        {
          "text": "At least ten people need to be willing to pay 299 UAH before proceeding.",
          "evidence": [20]
        },
        {
          "text": "A 100 % discount promo code is stored locally in the app bundle.",
          "evidence": [20]
        }
      ]
    },
    {
      "id": "security-password",
      "title": "Security concerns about password storage",
      "claims": [
        {
          "text": "The source code might be searchable to locate the stored password.",
          "evidence": [21]
        },
        {
          "text": "Most LinkedIn users could potentially hack the password without difficulty.",
          "evidence": [28]
        }
      ]
    },
    {
      "id": "project-legitimacy",
      "title": "Perception of project legitimacy / scam concerns",
      "claims": [
        {
          "text": "The project is positioned as a local‑first app with live USD/UAH updates, but the paid component is actually bundled.",
          "evidence": [29]
        },
        {
          "text": "The project is described as a “free vibe code” with low seriousness, leading participants to call it a possible scam.",
          "evidence": [30, 32, 33, 34]
        }
      ]
    }
  ],
  "decisions": [
    {
      "text": "The group decided not to purchase a domain.",
      "evidence": [9]
    },
    {
      "text": "The chosen cross‑platform stack is Flutter.",
      "evidence": [12]
    },
    {
      "text": "The calculator will be limited to UAH‑only calculations.",
      "evidence": [19]
    },
    {
      "text": "Pricing is set at 299 UAH with a 100 % discount promo code stored locally.",
      "evidence": [20]
    }
  ],
  "openQuestions": [
    {
      "text": "Can the source code be searched to find the stored password?",
      "evidence": [21]
    }
  ]
}
